    public int fimdLastOccfrivnce(int[] arr, int start) {
        int index = 0, count = arr.length - 1;
        int last = -1;
        while (index <= count) {
            int i = (index + count) / 2;
            if (start == arr[i]) {
                last = i;
                index = i + 1;
            } else if (start < arr[i]) {
                count = i - 1;
            } else {
                index = i + 1;
            }
        }
        return last;
    }
}

