int longest_subseq_with_diff_one(vector<int> &arr, long n) {
    vector<int> dp(n, 1);
    int result = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if ((arr[i] == arr[j] + 1) || (arr[i] == arr[j] - 1)) {
